import { createServer, request } from 'node:http';
import { healthResponse } from '@demo-app/shared';

const SERVICE = 'gateway';
const VERSION = '0.1.0';
const PORT = Number(process.env.PORT ?? 4000);

/** Path prefix → upstream service base URL. */
const routes: Record<string, string> = {
  '/api/v1/users': process.env.USERS_URL ?? 'http://localhost:4001',
  '/api/v1/orders': process.env.ORDERS_URL ?? 'http://localhost:4002',
  '/api/v1/notifications': process.env.NOTIFICATIONS_URL ?? 'http://localhost:4003',
};

const server = createServer((req, res) => {
  const url = req.url ?? '/';
  if (url === '/health' || url === '/ready') {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify(healthResponse(SERVICE, VERSION)));
    return;
  }

  const prefix = Object.keys(routes).find((key) => url === key || url.startsWith(key + '/'));
  if (!prefix) {
    res.writeHead(404, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: 'no route for ' + url }));
    return;
  }

  const target = new URL(routes[prefix] + url);
  const upstream = request(
    {
      hostname: target.hostname,
      port: target.port,
      path: target.pathname + target.search,
      method: req.method,
      headers: { ...req.headers, host: target.host },
    },
    (upstreamRes) => {
      res.writeHead(upstreamRes.statusCode ?? 502, upstreamRes.headers);
      upstreamRes.pipe(res);
    }
  );
  upstream.on('error', (error) => {
    res.writeHead(502, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: 'upstream ' + prefix + ' unavailable', detail: String(error) }));
  });
  req.pipe(upstream);
});

server.listen(PORT, () => {
  console.log('[' + SERVICE + '] listening on http://localhost:' + PORT);
  for (const [prefix, base] of Object.entries(routes)) {
    console.log('  ' + prefix + ' -> ' + base);
  }
});

